mapper.select:
select p.id, p.source_product_name sourceProductName, p.product_factory_id productFactoryId, mpf.factory_name productFactoryName, p.source_product_code sourceProductCode, p.source_product_url sourceProductUrl, p.head_img_url headImgUrl, p.logistics_name logisticsName, p.freight_cost freightCost, p.source_price sourcePrice, p.dispatch_time dispatchTime, p.steady_status steadyStatus, p.eval_with_image_count evalWithImageCount, p.supplier_name supplierName, p.repurchase_rate repurchaseRate, p.sales_count salesCount, (( SELECT MAX(h1.sales_count) FROM source_product_sales_history h1 WHERE h1.source_product_id = p.id AND h1.snapshot_time >= NOW() - INTERVAL 14 DAY ) - ( SELECT MAX(h2.sales_count) FROM source_product_sales_history h2 WHERE h2.source_product_id = p.id AND h2.snapshot_time < NOW() - INTERVAL 14 DAY )) salesCount14d, p.category_name categoryName, p.keyword keyword, p.trust_years trustYears, p.source_factory_id sourceFactoryId, p.crawl_time crawlTime, p.platform_type platformType, p.data_source dataSource, p.quality_grade qualityGrade from source_product p LEFT JOIN product_factory mpf on mpf.id = p.product_factory_id where p.is_deleted=0
and p.platform_type = #{productDto.platformType}
and p.source_product_name like concat('%',#{productDto.sourceProductName},'%')
and p.source_product_code = #{productDto.sourceProductCode}
and p.product_factory_id = #{productDto.productFactoryId}
and p.steady_status = #{productDto.steadyStatus}
and p.category_name = #{productDto.categoryName}
and p.supplier_name like concat('%',#{productDto.supplierName},'%')
and p.data_source = #{productDto.dataSource}
and p.quality_grade = #{productDto.qualityGrade}
order by case p.quality_grade when 'A' then 1 when 'B' then 2 when 'C' then 3 else 4 end asc, p.create_time desc
